// Consolidate all fetched data into one context object
const wb = $('Webhook').first().json.body;

const profileArr = $('Fetch Brand Profile').first().json;
const profile = Array.isArray(profileArr) ? profileArr[0] : profileArr;

const inspirationArr = $('Fetch Inspiration Accounts').first().json;
const inspiration = Array.isArray(inspirationArr) ? inspirationArr : [];

const settingsArr = $('Fetch Calendar Settings').first().json;
const settings = Array.isArray(settingsArr) ? settingsArr[0] : settingsArr;

const voiceArr = $('Fetch Brand Voice').first().json;
const voice = Array.isArray(voiceArr) ? voiceArr[0] : voiceArr;

const postsCount = wb.posts_count || 7;
const weekOf = wb.week_of || new Date().toISOString().slice(0, 10);

// Build posting day schedule (distribute across the week)
const daysOfWeek = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const postingDays = daysOfWeek.slice(0, Math.min(postsCount, 7));

// Content mix from settings
const contentMix = settings?.content_mix || { educational: 40, promotional: 20, entertainment: 30, behind_scenes: 10 };

// Build content type schedule based on mix percentages
const contentSchedule = [];
const sortedTypes = Object.entries(contentMix).sort((a, b) => b[1] - a[1]);
for (let i = 0; i < postsCount; i++) {
  const idx = i % sortedTypes.length;
  contentSchedule.push(sortedTypes[idx][0]);
}

// Build inspiration summary
const inspirationSummary = inspiration.slice(0, 8).map(acc => 
  `${acc.platform}/${acc.handle} (${acc.category}) — ${acc.why || 'inspiring content style'}`
).join('\n');

return [{
  run_id: wb.run_id,
  org_id: wb.org_id,
  week_of: weekOf,
  posts_count: postsCount,
  posting_days: postingDays,
  content_schedule: contentSchedule,
  callback_url: wb.callback_url,
  // Brand context
  profile: profile || {},
  inspiration_summary: inspirationSummary,
  settings: settings || {},
  voice: voice || {},
}];

