// Parse GPT response and save all suggestions + variations to Supabase
const gptRes = $input.first().json;
const ctx = $('Build Generation Context').first().json;

const supaUrl = process.env.SUPABASE_URL;
const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

let parsed;
try {
  const content = gptRes.choices[0].message.content;
  parsed = JSON.parse(content);
} catch(e) {
  throw new Error('GPT response parse failed: ' + gptRes.choices?.[0]?.message?.content?.slice(0, 200));
}

const suggestions = parsed.suggestions || [];
const savedIds = [];

for (const sug of suggestions) {
  const { variations = [], ...sugData } = sug;

  // Insert suggestion
  const insertRes = await $helpers.httpRequest({
    method: 'POST',
    url: `${supaUrl}/rest/v1/content_suggestions`,
    headers: {
      'apikey': supaKey,
      'Authorization': `Bearer ${supaKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: JSON.stringify({
      org_id:               ctx.org_id,
      run_id:               ctx.run_id,
      title:                sugData.title,
      topic:                sugData.topic,
      content_type:         sugData.content_type,
      target_platforms:     sugData.target_platforms || ctx.settings?.platforms || [],
      best_posting_time:    sugData.best_posting_time,
      week_of:              ctx.week_of,
      performance_score:    sugData.performance_score || 60,
      virality_score:       sugData.virality_score || 55,
      image_type:           sugData.image_type || 'ai_generated',
      image_prompt:         sugData.image_prompt || null,
      image_description:    sugData.image_description || null,
      benchmark_reference:  sugData.benchmark_reference || null,
      optimization_tips:    sugData.optimization_tips || [],
      engagement_prediction: sugData.engagement_prediction || {},
      status:               'pending',
    })
  });

  const saved = Array.isArray(insertRes) ? insertRes[0] : insertRes;
  if (!saved?.id) continue;

  savedIds.push(saved.id);

  // Insert variations
  for (const v of variations) {
    await $helpers.httpRequest({
      method: 'POST',
      url: `${supaUrl}/rest/v1/content_variations`,
      headers: {
        'apikey': supaKey,
        'Authorization': `Bearer ${supaKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify({
        suggestion_id:   saved.id,
        org_id:          ctx.org_id,
        variation_label: v.variation_label,
        caption:         v.caption,
        hashtags:        v.hashtags || [],
        hook:            v.hook || null,
        cta:             v.cta || null,
        tone:            v.tone || null,
        predicted_reach: v.predicted_reach || 0,
        is_selected:     v.variation_label === 'A',
      })
    });
  }
}

console.log(`[Content Calendar] Saved ${savedIds.length} suggestions with variations for org ${ctx.org_id}`);

return [{ savedIds, count: savedIds.length, ctx }];

const crypto = require('crypto');
const { ctx, count, savedIds } = $input.first().json;

const payload = {
  workflow_type: 'content_generation',
  status: 'complete',
  run_id: ctx.run_id,
  org_id: ctx.org_id,
  output_summary: {
    suggestions_created: count,
    suggestion_ids: savedIds,
    week_of: ctx.week_of,
  }
};

const body = JSON.stringify(payload);
const secret = process.env.N8N_HMAC_SECRET || '';
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{ body, signature, callback_url: ctx.callback_url }];

